-- @adminigloo/wallet 0.1.0: spendable balances and their ledger.
--
-- For a project that does not run drizzle-kit. A project generated by
-- @adminigloo/create-app gets these tables through its own migrations instead
-- (src/db/schema.ts re-exports @adminigloo/wallet/schema).

CREATE TABLE IF NOT EXISTS "wallet_balances" (
  "holder_id" text NOT NULL,
  "unit" text NOT NULL,
  "balance" integer NOT NULL DEFAULT 0,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "wallet_balances_pkey" PRIMARY KEY ("holder_id", "unit"),
  CONSTRAINT "wallet_balances_never_negative" CHECK ("balance" >= 0)
);

CREATE TABLE IF NOT EXISTS "wallet_ledger" (
  "id" bigserial PRIMARY KEY,
  "holder_id" text NOT NULL,
  "unit" text NOT NULL,
  "delta" integer NOT NULL,
  "reason" text NOT NULL,
  "ref" text NOT NULL,
  "note" text,
  "actor_id" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "wallet_ledger_reason_known" CHECK ("reason" in ('grant', 'spend', 'refund', 'adjust')),
  CONSTRAINT "wallet_ledger_zero_only_refund" CHECK ("delta" <> 0 or "reason" = 'refund')
);

CREATE UNIQUE INDEX IF NOT EXISTS "wallet_ledger_once_idx" ON "wallet_ledger" ("holder_id", "unit", "reason", "ref");
CREATE INDEX IF NOT EXISTS "wallet_ledger_holder_idx" ON "wallet_ledger" ("holder_id", "unit", "id");
CREATE INDEX IF NOT EXISTS "wallet_ledger_created_idx" ON "wallet_ledger" ("created_at");
